===== TelephoneE164 =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Normalizes a telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
 * form: a leading {@code '+'} followed by 8 to 15 digits.
 *
 * <p>Rules:
 * <ul>
 *   <li>spaces, dashes and brackets are stripped;</li>
 *   <li>when the input already carries a leading {@code '+'} (a country code), it is kept
 *       and the remaining digits are used verbatim;</li>
 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
 *       dropped from the national digits;</li>
 *   <li>the result must have 8 to 15 digits after the {@code '+'}, else it is not valid E.164.</li>
 * </ul>
 *
 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
 * becomes {@code "+6421123456"}.
 */
public final class TelephoneE164 {

    private TelephoneE164() {
    }

    /**
     * Returns the E.164 form of {@code raw}, or {@code null} if it cannot form a valid E.164
     * number.
     */
    public static String normalize(String raw) {
        if (raw == null) {
            return null;
        }
        boolean hasCountryCode = raw.strip().startsWith("+");
        String digits = raw.replaceAll("\\D", "");
        String e164Digits;
        if (hasCountryCode) {
            e164Digits = digits;
        }
        else {
            String national = digits.startsWith("0") ? digits.substring(1) : digits;
            e164Digits = "61" + national;
        }
        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
            return null;
        }
        return "+" + e164Digits;
    }
}

===== OwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Shared handling of an owner's optional {@code email}. Email is optional; when present
 * it must be a syntactically valid address and is stored and returned lower-cased.
 */
final class OwnerEmail {

    /**
     * A pragmatic "syntactically valid address" check: a non-empty local part, an
     * {@code @}, and a domain of at least two dot-separated labels — none of which may
     * contain whitespace or a further {@code @}.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");

    private OwnerEmail() {
    }

    /**
     * Normalize a supplied email. A {@code null} or blank value is treated as absent and
     * returns {@code null}. A present value must match {@link #EMAIL} or an
     * {@link InvalidEmailException} (400) is thrown; otherwise it is returned lower-cased.
     */
    static String normalize(String email) throws InvalidEmailException {
        if (email == null) {
            return null;
        }
        String trimmed = email.strip();
        if (trimmed.isEmpty()) {
            return null;
        }
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException("Email is not a syntactically valid address: " + email);
        }
        return trimmed.toLowerCase(Locale.ROOT);
    }
}

